def rellenar(apps, schema_editor):
    """Entregables anteriores al Sprint 2: código CT-<año de creación>-<id> y recepción = fecha local de creación."""
    Entregable = apps.get_model("entregables", "Entregable")
    prefijo = getattr(settings, "CODIGO_PREFIJO", "CT")
    # Se leen antes de escribir: SQLite no aísla una lectura en curso de las escrituras de la misma conexión.
    pendientes = list(Entregable.objects.filter(codigo__isnull=True).values_list("pk", "creado_en", "fecha_recepcion"))
    for pk, creado_en, recepcion in pendientes:
        local = timezone.localtime(creado_en)  # America/Lima
        Entregable.objects.filter(pk=pk).update(
            codigo=f"{prefijo}-{local.year}-{pk:05d}", fecha_recepcion=recepcion or local.date()
        )


